class Solution {
public:
    bool reorderedPowerOf2(int n) {
        static int sigs[34][10];
        static bool init = false;
        if (!init) {
            long long p = 1;
            for (int i = 0; i < 34; i++) {
                long long q = p;
                while (q) { sigs[i][q % 10]++; q /= 10; }
                p *= 2;
            }
            init = true;
        }
        int cnt[10] = {0};
        int m = n;
        while (m) { cnt[m % 10]++; m /= 10; }
        for (int i = 0; i < 34; i++) {
            bool match = true;
            for (int d = 0; d < 10; d++) {
                if (sigs[i][d] != cnt[d]) { match = false; break; }
            }
            if (match) return true;
        }
        return false;
    }
};
